mapper.select:
SELECT p.partner_id, p.company_id, p.partner_code, p.partner_name, p.partner_type, p.source_module, p.source_id, p.tax_number, p.invoice_title, p.invoice_address, p.invoice_phone, p.payment_days, p.settlement_type, p.currency, p.credit_limit, p.credit_used, p.dept_id, p.user_id, p.status, p.create_by, p.create_time, p.update_by, p.update_time, p.remark FROM fin_partner p
AND p.partner_name LIKE CONCAT('%', #{partnerName}, '%')
AND p.partner_code LIKE CONCAT('%', #{partnerCode}, '%')
AND p.partner_type = #{partnerType}
AND p.status = #{status}
AND p.del_flag = '0'
AND ${params.dataScope}
ORDER BY p.partner_type, p.partner_code, p.partner_id


WHERE source_module = #{sourceModule}
  AND source_id     = #{sourceId}
  AND del_flag      = '0'
LIMIT 1

mapper.update:
UPDATE fin_partner
partner_code = #{partnerCode}, partner_name = #{partnerName}, partner_type = #{partnerType}, tax_number = #{taxNumber}, invoice_title = #{invoiceTitle}, invoice_address = #{invoiceAddress}, invoice_phone = #{invoicePhone}, payment_days = #{paymentDays}, settlement_type = #{settlementType}, credit_limit = #{creditLimit}, status = #{status}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
WHERE partner_id = #{partnerId}

UPDATE fin_partner SET del_flag = '2', update_time = sysdate()
WHERE partner_id IN

    #{id}

mapper.select:
SELECT COUNT(*) FROM fin_partner
WHERE partner_name = #{partnerName}
  AND partner_type = #{partnerType}
  AND del_flag = '0'
AND partner_id != #{partnerId}
